package com.alsafa.native4;import android.app.Activity;import android.os.Bundle;import android.view.Gravity;import android.view.ViewGroup;import android.widget.*;import com.alsafa.native4.core.*;import java.util.*;
public final class WatchAdvisorActivity extends Activity{private CoreDb db;private CoreProductCatalog catalog;private Spinner range;private LinearLayout results;private TextView count;private final String[] labels={"كل الأسعار","10–20 USD","25–40 USD","50–100 USD","100–300 USD"};
@Override public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_watch_advisor);db=new CoreDb(this);catalog=new CoreProductCatalog(db);range=findViewById(R.id.priceRange);results=findViewById(R.id.advisorResults);count=findViewById(R.id.advisorCount);range.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels));range.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int pos,long id){render();}public void onNothingSelected(android.widget.AdapterView<?> p){}});findViewById(R.id.resetAdvisor).setOnClickListener(v->{range.setSelection(0);render();});findViewById(R.id.pageBack).setOnClickListener(v->finish());render();}
private void render(){results.removeAllViews();List<CoreProductCatalog.ProductHit> all=catalog.search("",50);int n=0;for(CoreProductCatalog.ProductHit p:all){if(p.quantity<=0||!matches(p.salePrice,range.getSelectedItemPosition()))continue;n++;TextView t=new TextView(this);t.setGravity(Gravity.END);t.setPadding(dp(12),dp(12),dp(12),dp(12));t.setBackgroundResource(R.drawable.alsafa_card);t.setText(p.name+(p.ref.isEmpty()?"":" — "+p.ref)+"\n"+p.salePrice+" "+p.currency+" — المتوفر: "+p.quantity);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);lp.setMargins(0,dp(5),0,dp(5));results.addView(t,lp);}count.setText("النتائج المتوفرة: "+n);}
private boolean matches(double v,int i){if(i==0)return true;if(i==1)return v>=10&&v<=20;if(i==2)return v>=25&&v<=40;if(i==3)return v>=50&&v<=100;return v>=100&&v<=300;}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}}
